    clave text, name text, country text, business_unit text, extra_countries text[],
    platform_investment numeric, completed_steps text[], completed_at timestamptz,
    created_at timestamptz, data jsonb)
),
upd as (
  update public.campaigns c
     set platform_investment = g.platform_investment,
         data = coalesce(c.data, '{}'::jsonb) || jsonb_build_object('google_ads', g.data->'google_ads'),
         completed_steps = case when g.completed_at is not null and not ('finished' = any(coalesce(c.completed_steps, '{}')))
                                then coalesce(c.completed_steps, '{}') || array['finished'] else c.completed_steps end,
         completed_at = case when g.completed_at is not null and c.completed_at is null then g.completed_at else c.completed_at end
    from g
   where c.type = 'paid' and c.data->'google_ads'->>'clave_externa' = g.clave
  returning c.id
)
insert into public.campaigns (name, type, country, business_unit, extra_countries, platform_investment,
                              completed_steps, completed_at, created_at, data)
select g.name, 'paid', g.country, g.business_unit, g.extra_countries, g.platform_investment,
       g.completed_steps, g.completed_at, g.created_at, g.data
  from g
 where not exists (select 1 from public.campaigns c
                    where c.type = 'paid' and c.data->'google_ads'->>'clave_externa' = g.clave);

-- Verificación: debería dar 31 campañas y USD 5707.81
select business_unit, count(*) as campanas, sum(platform_investment) as inversion_usd,
       count(*) filter (where completed_at is not null) as completadas
  from public.campaigns
 where type = 'paid' and data->'google_ads'->>'clave_externa' = any(array['gads:1606422184:24251193083', 'gads:1606422184:24256799944', 'gads:1606422184:24256799938', 'gads:1606422184:24256799950', 'gads:1606422184:24256799941', 'gads:1606422184:24256799947', 'gads:1606422184:24052475277+6527967282:23730225570', 'gads:1606422184:24052475400+6527967282:23840019312', 'gads:1606422184:24052475415+6527967282:23848448294', 'gads:1606422184:24052475409+6527967282:23845340120', 'gads:1606422184:24057321047+6527967282:23853091093', 'gads:1606422184:24052475274+6527967282:23560818640', 'gads:1606422184:24052475271+6527967282:23556195596', 'gads:1606422184:24057321086+6527967282:23870791342', 'gads:1606422184:24057321059+6527967282:23860528206', 'gads:1606422184:24057321092+6527967282:23870835547', 'gads:1606422184:24057321083+6527967282:23870225920', 'gads:1606422184:24057321074+6527967282:23865793847', 'gads:1606422184:24057321089+6527967282:23870806531', 'gads:6527967282:23993092024', 'gads:1606422184:24057321098', 'gads:1606422184:24164538908', 'gads:1606422184:24164537216', 'gads:1606422184:24329920730', 'gads:1606422184:24052475268+6527967282:23556159815', 'gads:1606422184:24057321065+6527967282:23861207967', 'gads:1606422184:24057321080+6527967282:23866443026', 'gads:1606422184:24057321068+6527967282:23861207970', 'gads:1606422184:24057321077+6527967282:23866443020', 'gads:1606422184:24057321062+6527967282:23861207688', 'gads:1606422184:24057321095+6527967282:23870903698'])
